import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream is = System.in;
        OutputStream os = System.out;
        InputReader in = new InputReader(is);
        PrintWriter out = new PrintWriter(os);
        Problem solver = new Problem();
        solver.solve(in, out);
        out.close();
    }

    static class Problem {
        static final int MOD = 998244353;

        void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();
            int[] poly = new int[10];
            for (int i = 0; i < k; i++) poly[in.nextInt()] = 1;
            int[] res = {1};
            int exp = n / 2;
            while (exp > 0) {
                if ((exp & 1) == 1) res = polyMul(res, poly);
                exp >>= 1;
                if (exp > 0) poly = polyMul(poly, poly);
            }
            long sum = 0;
            for (int x : res) sum = (sum + (long) x * x) % MOD;
            out.println((int) sum);
        }

        int[] polyMul(int[] a, int[] b) {
            int need = a.length + b.length - 1;
            int n = Math.max(2, Integer.highestOneBit(need - 1) << 1);
            double[] ar = new double[n], ai = new double[n];
            for (int i = 0; i < a.length; i++) {
                int x = (a[i] % MOD + MOD) % MOD;
                ar[i] = x & 0x7FFF;
                ai[i] = x >> 15;
            }
            fft(ar, ai, false);
            double[] br = new double[n], bi = new double[n];
            if (a == b) {
                System.arraycopy(ar, 0, br, 0, n);
                System.arraycopy(ai, 0, bi, 0, n);
            } else {
                for (int i = 0; i < b.length; i++) {
                    int x = (b[i] % MOD + MOD) % MOD;
                    br[i] = x & 0x7FFF;
                    bi[i] = x >> 15;
                }
                fft(br, bi, false);
            }
            double[] fr = new double[n], fi = new double[n];
            double[] gr = new double[n], gi = new double[n];
            double inv = 0.25 / n;
            for (int i = 0; i < n; i++) {
                int j = (n - i) & (n - 1);
                double a1r = ar[i] + ar[j], a1i = ai[i] - ai[j];
                double a2r = ai[i] + ai[j], a2i = ar[j] - ar[i];
                double b1r = (br[i] + br[j]) * inv, b1i = (bi[i] - bi[j]) * inv;
                double b2r = (bi[i] + bi[j]) * inv, b2i = (br[j] - br[i]) * inv;
                fr[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
                fi[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
                gr[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
                gi[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
            }
            fft(fr, fi, true);
            fft(gr, gi, true);
            int[] ret = new int[need];
            for (int i = 0; i < need; i++) {
                long p = (long) (fr[i] + 0.5);
                long q = (long) (gr[i] + 0.5);
                long r = (long) (fi[i] + 0.5);
                ret[i] = (int) ((p + ((q % MOD) << 15) + ((r % MOD) << 30)) % MOD);
            }
            return ret;
        }

        void fft(double[] re, double[] im, boolean inverse) {
            int n = re.length;
            int shift = 32 - Integer.numberOfTrailingZeros(n);
            for (int i = 1; i < n; i++) {
                int j = Integer.reverse(i << shift);
                if (i < j) {
                    double t = re[i]; re[i] = re[j]; re[j] = t;
                    t = im[i]; im[i] = im[j]; im[j] = t;
                }
            }
            for (int len = 2; len <= n; len <<= 1) {
                int half = len >> 1;
                double[] cos = new double[half], sin = new double[half];
                for (int k = 0; k < half; k++) {
                    cos[k] = Math.cos(2 * Math.PI * k / len * (inverse ? -1 : 1));
                    sin[k] = Math.sin(2 * Math.PI * k / len * (inverse ? -1 : 1));
                }
                for (int i = 0; i < n; i += len) {
                    for (int j = 0; j < half; j++) {
                        double uR = re[i + j], uI = im[i + j];
                        double vR = re[i + j + half] * cos[j] - im[i + j + half] * sin[j];
                        double vI = re[i + j + half] * sin[j] + im[i + j + half] * cos[j];
                        re[i + j] = uR + vR;
                        im[i + j] = uI + vI;
                        re[i + j + half] = uR - vR;
                        im[i + j + half] = uI - vI;
                    }
                }
            }
        }
    }

    static class InputReader {
        final InputStream is;
        final byte[] buf = new byte[1024];
        int pos;
        int size;

        public InputReader(InputStream is) {
            this.is = is;
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c))
                c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res = res * 10 + c - '0';
                c = read();
            } while (!isWhitespace(c));
            return res * sign;
        }

        int read() {
            if (size == -1)
                throw new InputMismatchException();
            if (pos >= size) {
                pos = 0;
                try {
                    size = is.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (size <= 0)
                    return -1;
            }
            return buf[pos++] & 255;
        }

        static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
